    private void simplePayment(ComboBox<RepairChoice> repairs){
        if(repairs.getValue()==null){FxSupport.info(content,"Payment","Select a repair first.");return;}
        int repairId=selected(repairs);
        FxSupport.task(()->workflow.billingSummary(session,repairId),bill->{
            if(!Boolean.TRUE.equals(bill.get("can_pay"))){FxSupport.info(content,"Payment unavailable","A finalized, unpaid repair bill is required. Current status: "+format(bill.get("repair_status")));return;}
            Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle("Record shop payment ? repair #"+repairId);dialog.initOwner(content.getScene().getWindow());
            dialog.getDialogPane().getStylesheets().add(getClass().getResource("crsm.css").toExternalForm());
            TextField amount=new TextField(format(bill.get("balance_due")));ComboBox<String> method=new ComboBox<>(FXCollections.observableArrayList("Cash","GCash","Bank transfer","Card"));method.setValue("Cash");
            Label error=new Label();error.setWrapText(true);
            dialog.getDialogPane().setContent(new VBox(12,new Label("Final bill: PHP "+format(bill.get("final_cost"))),new Label("Net paid: PHP "+format(bill.get("net_paid"))),new Label("Balance due: PHP "+format(bill.get("balance_due"))),new Label("Record only money received at the shop. Partial payments are supported."),new Label("Amount received (PHP)"),amount,new Label("Payment method"),method,error));
            Button qr=new Button("Show demo payment QR");qr.getStyleClass().add("ghost-button");qr.setOnAction(e->PaymentDialogs.demoQr(amount,bill));((VBox)dialog.getDialogPane().getContent()).getChildren().add(qr);
            dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);Button save=(Button)dialog.getDialogPane().lookupButton(ButtonType.OK);save.setText("Confirm received payment");
            save.addEventFilter(javafx.event.ActionEvent.ACTION,event->{event.consume();String value=amount.getText(),paymentMethod=method.getValue();save.setDisable(true);dialog.getDialogPane().lookupButton(ButtonType.CANCEL).setDisable(true);error.setText("Saving payment...");
                FxSupport.task(()->workflow.recordPayment(session,repairId,value,paymentMethod),receipt->{dialog.close();showPage(currentPage);FxSupport.info(content,"Payment recorded","Receipt: "+receipt+". The balance and pickup eligibility have been updated.");},failure->{save.setDisable(false);dialog.getDialogPane().lookupButton(ButtonType.CANCEL).setDisable(false);error.setText(failure.getMessage());});});
            dialog.show();
        },failure->showError(content,failure));
    }
