    private void uploadPhotos(VBox root,int repairId){List<File>files=new ArrayList<>(selectedPhotos);FxSupport.task(()->{for(File file:files){String path=new SupabaseStorageService().uploadRepairPhoto(session,repairId,file.toPath());workflow.registerPhoto(session,repairId,path);}return files.size();},count->FxSupport.info(root,"Request submitted","Repair request #"+repairId+" saved with "+count+" photo(s)."),error->showError(root,error));}
    private void addField(GridPane g,String label,Control control,int row){
        if("Drop-off date".equals(label) && control instanceof TextField text){
            DatePicker picker=new DatePicker();try{picker.setValue(LocalDate.parse(text.getText()));}catch(RuntimeException ignored){picker.setValue(LocalDate.now().plusDays(1));}
            picker.valueProperty().addListener((o,a,b)->{if(b!=null)text.setText(b.toString());});control=picker;
        }
        // Keep the service picker a normal, non-editable ComboBox.  The previous
        // self-filtering editor replaced the item list while JavaFX was committing
        // a selection; that could discard the selected service and make the intake
        // form appear to reset.  The catalog is already sorted and small enough to
        // browse safely, so selection must remain stable during async loading.
        if("Service".equals(label) && control instanceof ComboBox<?> combo){
            combo.setEditable(false);
            combo.setPromptText("Choose a service");
        }
        g.add(new Label(label),0,row);g.add(control,1,row);GridPane.setHgrow(control,Priority.ALWAYS);
    }
