            Label summary=new Label(bill.get("final_cost")==null?"The final bill will be available when technical work is complete.":"Final bill: PHP "+format(bill.get("final_cost"))+"    Net paid: PHP "+format(bill.get("net_paid"))+"    Balance due: PHP "+format(bill.get("balance_due")));summary.setWrapText(true);
            Label state=new Label("Payment: "+format(bill.get("payment_status"))+" ? Repair: "+format(bill.get("repair_status")));state.getStyleClass().add("status-label");
